 import React from 'react'
import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom'
import { AuthProvider, useAuth } from './contexts/AuthContext'
import Login from './components/auth/Login'
import Register from './components/auth/Register'

// TEMPORARY HOME PAGE - We'll build the real one later
function HomePage() {
  const { user, profile, signOut } = useAuth()

  return (
    <div className="min-h-screen bg-gray-100 p-8">
      <div className="max-w-4xl mx-auto">
        <div className="bg-white rounded-xl shadow-lg p-8">
          <div className="flex justify-between items-center mb-6">
            <div>
              <h1 className="text-3xl font-bold text-green-700">🏠 Home</h1>
              <p className="text-gray-600 mt-1">
                Welcome, {profile?.full_name || profile?.username || user?.email || 'User'}!
              </p>
            </div>
            <button 
              onClick={signOut}
              className="bg-red-500 text-white px-4 py-2 rounded-lg hover:bg-red-600 transition"
            >
              Sign Out
            </button>
          </div>
          <div className="bg-gray-50 rounded-lg p-6 text-center">
            <p className="text-gray-500">📊 Your dashboard and predictions will appear here.</p>
            <p className="text-sm text-gray-400 mt-2">Coming soon: Live matches, AI predictions, and leaderboard!</p>
          </div>
        </div>
      </div>
    </div>
  )
}

// Protected Route wrapper
function PrivateRoute({ children }) {
  const { user, loading } = useAuth()

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="text-xl text-gray-500">Loading...</div>
      </div>
    )
  }

  return user ? children : <Navigate to="/login" />
}

// Main routes
function AppRoutes() {
  return (
    <Routes>
      <Route path="/login" element={<Login />} />
      <Route path="/register" element={<Register />} />
      <Route path="/" element={
        <PrivateRoute>
          <HomePage />
        </PrivateRoute>
      } />
    </Routes>
  )
}

// Main App
function App() {
  return (
    <AuthProvider>
      <BrowserRouter>
        <AppRoutes />
      </BrowserRouter>
    </AuthProvider>
  )
}

export default App
